    if (result == -1) {
        printf("Error: File does not exist\n");
    } else {
        printf("File exists\n");
    }
    return 0;
}
```

### 2. Using Error Codes with Enum

Another way to return errors in C is by using an enum to define a set of error codes.

```c
#include <stdio.h>

// Define an enum for error codes
typedef enum {
    SUCCESS,
    FILE_NOT_FOUND,
    INVALID_INPUT
} ErrorCode;

// Function to check if a file exists
ErrorCode check_file_exists(const char *filename) {
    // Simulate a file operation
    if (/* file operation fails */) {
        return FILE_NOT_FOUND;
    }
    return SUCCESS;
}

int main() {
    const char *filename = "example.txt";
    ErrorCode result = check_file_exists(filename);
    switch (result) {
        case SUCCESS:
            printf("File exists\n");
            break;
        case FILE_NOT_FOUND:
            printf("Error: File does not exist\n");
            break;
        default:
            printf("Unknown error\n");
            break;
    }
    return 0;
}
```

### 3. Using Error Structures

You can also return a structure containing error information.

```c
#include <stdio.h>
#include <stdlib.h>

// Define a structure for error information
typedef struct {
    int code;
    char *message;
} Error;

// Function to check if a file exists
Error check_file_exists(const char *filename) {
    // Simulate a file operation
    if (/* file operation fails */) {
        Error error;
        error.code = -1;
        error.message = "File does not exist";
        return error;
    }
    Error error;
    error.code = 0;
    error.message = "File exists";
    return error;
}

int main() {
    const char *filename = "example.txt";
    Error result = check_file_exists(filename);
    if (result.code == -1) {
        printf("Error: %s\n", result.message);
    } else {
        printf("File exists\n");
    }
    return 0;
}
```

### 4. Using Error Functions

You can also use a separate function to handle errors.

```c
#include <stdio.h>
#include <stdlib.h>

// Function to check if a file exists
int check_file_exists(const char *filename) {
    // Simulate a file operation
    if (/* file operation fails */) {
        return -1;
    }
    return 1;
}

// Function to handle errors
void handle_error(int code) {
