        case -1:
            printf("Error: File does not exist\n");
            break;
        default:
            printf("Unknown error\n");
            break;
    }
}

int main() {
    const char *filename = "example.txt";
    int result = check_file_exists(filename);
    handle_error(result);
    return 0;
}
```

### 5. Using Error Macros

You can also use macros to define error handling functions.

```c
#include <stdio.h>
#include <stdlib.h>

// Define a macro for error handling
#define HANDLE_ERROR(code) \
    switch (code) { \
        case -1: \
            printf("Error: File does not exist\n"); \
            break; \
        default: \
            printf("Unknown error\n"); \
            break; \
    }

// Function to check if a file exists
int check_file_exists(const char *filename) {
    // Simulate a file operation
    if (/* file operation fails */) {
        return -1;
    }
    return 1;
}

int main() {
