        for (Car car : cars) {
            String color = car.getColor();
            colorCount.put(color, colorCount.getOrDefault(color, 0) + 1);
        }

        // Find the color with the maximum count
        String mostPopularColor = Collections.max(colorCount.entrySet(), Comparator.comparingInt(Map.Entry::getValue)).getKey();

        // Return a map containing the count and color of the most popular car color
        Map<String, Integer> result = new HashMap<>();
        result.put("color", mostPopularColor);
